mapper.update:
UPDATE payment SET state='SUCCEEDED',channel_transaction_id=#{transactionId},updated_at=#{now},version=version+1
WHERE id=CAST(#{paymentId} AS UNSIGNED) AND order_id=CAST(#{orderId} AS UNSIGNED)
  AND channel='MOCK' AND state IN ('CREATED','PROCESSING') AND version=#{version}

UPDATE sales_order SET state='PAID',paid_at=#{now},updated_at=#{now},version=version+1
WHERE id=CAST(#{orderId} AS UNSIGNED) AND state=#{state} AND state IN ('UNPAID','CLOSING')
  AND paid_at IS NULL AND cancelled_at IS NULL AND version=#{version}
